window.__votdWeek && window.__votdWeek({"week":"2029-04-02","reading":"Doctrine and Covenants 27–28","days":[{"d":"2029-04-02","ref":"D&C 27:11","b":"D&C","c":27,"v":11,"he":"וְגַם עִם מִיכָאֵל הוּא אָדָם אֲבִי כֹל שַׂר הַכֹּל עַתִּיק יוֹמִין׃","en":"And also with Michael, or Adam, the father of all, the prince of all, the ancient of days;"},{"d":"2029-04-03","ref":"D&C 27:14","b":"D&C","c":27,"v":14,"he":"וְגַם עִם כׇּל אֲשֶׁר נָתַן לִי אָבִי מִן הָעוֹלָם׃","en":"And also with all those whom my Father hath given me out of the world."},{"d":"2029-04-04","ref":"D&C 27:15","b":"D&C","c":27,"v":15,"he":"לָכֵן הָרִימוּ לְבַבְכֶם וְגִילוּ וְחִגְרוּ מׇתְנֵיכֶם וּקְחוּ עֲלֵיכֶם אֶת־כׇּל־נִשְׁקִי לְמַעַן תּוּכְלוּ לַעֲמֹד בְּיוֹם הָרָעָה וּבַעֲשׂוֹתְכֶם הַכֹּל תּוּכְלוּ לַעֲמֹד׃","en":"Wherefore, lift up your hearts and rejoice, and gird up your loins, and take upon you my whole armor, that ye may be able to withstand the evil day, having done all, that ye may be able to stand."},{"d":"2029-04-05","ref":"D&C 27:16","b":"D&C","c":27,"v":16,"he":"עִמְדוּ אֵפוֹא מׇתְנֵיכֶם חֲגוּרִים בֶּאֱמֶת וּלְבוּשִׁים שִׁרְיוֹן הַצְּדָקָה וְרַגְלֵיכֶם מְנֻעָלוֹת מוּכָנוֹת בְּשׂוֹרַת הַשָּׁלוֹם אֲשֶׁר שָׁלַחְתִּי מַלְאָכַי לְמָסְרָהּ לָכֶם׃","en":"Stand, therefore, having your loins girt about with truth, having on the breastplate of righteousness, and your feet shod with the preparation of the gospel of peace, which I have sent mine angels to commit unto you;"},{"d":"2029-04-06","ref":"D&C 28:2","b":"D&C","c":28,"v":2,"he":"אַךְ הִנֵּה אָמֵן אָמֵן אֲנִי אֹמֵר לְךָ לֹא יִמָּנֶה אִישׁ לְקַבֵּל מִצְוֹת וְחֶזְיֹנוֹת בַּכְּנֵסִיָּה הַזֹּאת זוּלָתִי עַבְדִּי יוֹסֵף סְמִית הַבֵּן כִּי הוּא מְקַבְּלָם כְּמֹשֶׁה׃","en":"But, behold, verily, verily, I say unto thee, no one shall be appointed to receive commandments and revelations in this church excepting my servant Joseph Smith, Jun., for he receiveth them even as Moses."},{"d":"2029-04-07","ref":"D&C 28:3","b":"D&C","c":28,"v":3,"he":"וְאַתָּה תִּשָּׁמַע לַדְּבָרִים אֲשֶׁר אֶתֵּן לוֹ כְּאַהֲרֹן לְהַגִּיד בֶּאֱמוּנָה אֶת־הַמִּצְוֹת וְהַחֶזְיֹנוֹת בְּכֹחַ וּבְסַמְכוּת לַכְּנֵסִיָּה׃","en":"And thou shalt be obedient unto the things which I shall give unto him, even as Aaron, to declare faithfully the commandments and the revelations, with power and authority unto the church."},{"d":"2029-04-08","ref":"D&C 28:4","b":"D&C","c":28,"v":4,"he":"וְאִם תִּנָּהֵג בָּעֵת מִן הָעִתִּים בְּיַד הַמְּנַחֵם לְדַבֵּר אוֹ לְלַמֵּד אוֹ בְּכׇל־עֵת בְּדֶרֶךְ מִצְוָה לַכְּנֵסִיָּה תּוּכַל לַעֲשׂוֹתוֹ׃","en":"And if thou art led at any time by the Comforter to speak or teach, or at all times by the way of commandment unto the church, thou mayest do it."}]});
